/* R1366 — Community Member offers, promotions, events and reviewed documents public projection */
(()=>{'use strict';
 const m=location.pathname.match(/^\/profiles\/(FR-[A-Z0-9]+-[A-Za-z0-9][A-Za-z0-9._-]{2,100})\/$/);if(!m)return;
 const id=decodeURIComponent(m[1]),API='https://franklin-navigator-membership.onrender.com';
 const n=(t,x,c)=>{const e=document.createElement(t);if(x!==undefined)e.textContent=x;if(c)e.className=c;return e};
 const safe=v=>{try{const u=new URL(String(v||''));return u.protocol==='https:'&&!u.username&&!u.password?u:null}catch{return null}};
 const lang=()=>window.FranklinI18n?.language==='es'?'es':'en';
 const ES={
  'Coupon':'Cupón','Special offer':'Oferta especial','Sale':'Venta','Promotion':'Promoción','Event':'Evento','Community Member update':'Actualización de Miembro de la Comunidad',
  'Offers & events':'Ofertas y eventos','Community Member offers & events':'Ofertas y eventos de Miembros de la Comunidad','Current offers, promotions and events':'Ofertas, promociones y eventos actuales',
  'Code: ':'Código: ','Starts ':'Comienza ','Ends ':'Termina ','Through ':'Hasta ','Event details':'Detalles del evento','View details':'Ver detalles','View PDF document':'Ver documento PDF',
  'Community Member promotion':'Promoción de Miembro de la Comunidad','Provided by this Community Member. Franklin Navigator does not guarantee availability, terms or results.':'Proporcionado por este Miembro de la Comunidad. Franklin Navigator no garantiza disponibilidad, términos ni resultados.',
  'Community Member offer':'Oferta de Miembro de la Comunidad','Special offer for Franklin Navigator users':'Oferta especial para usuarios de Franklin Navigator','View offer':'Ver oferta','Offer provided by this Community Member. Franklin Navigator does not guarantee availability, terms or results.':'Oferta proporcionada por este Miembro de la Comunidad. Franklin Navigator no garantiza disponibilidad, términos ni resultados.'
 };
 const t=s=>lang()==='es'?(ES[s]||s):s;
 const kindLabel=k=>t(({COUPON:'Coupon',SPECIAL:'Special offer',SALE:'Sale',PROMOTION:'Promotion',EVENT:'Event'}[k]||'Community Member update'));
 const dateLabel=v=>{if(!v)return'';try{return new Intl.DateTimeFormat(lang()==='es'?'es-US':undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return''}};
 function addNav(){const nav=document.querySelector('.r1330-section-nav');if(!nav)return;let a=nav.querySelector('a[href="#member-offers-events"]');if(!a){a=n('a');a.href='#member-offers-events';const reviews=nav.querySelector('a[href="#reviews"]');reviews?nav.insertBefore(a,reviews):nav.append(a)}a.textContent=t('Offers & events')}
 function insertSection(section){const article=document.querySelector('.r22-profile-layout>article');if(!article)return false;document.querySelector('#member-offers-events')?.remove();const anchor=document.querySelector('#member-updates')||document.querySelector('#official-links')||document.querySelector('#manage');anchor?article.insertBefore(section,anchor):article.append(section);addNav();return true}
 function mediaUrl(x){try{return new URL(String(x||''),API).href}catch{return''}}
 function renderCurrent(items){if(!items.length)return false;const section=n('section','', 'hf35-member-module r1332-special-offer r1365-public-offers');section.id='member-offers-events';section.append(n('div',t('Community Member offers & events'),'eyebrow'),n('h2',t('Current offers, promotions and events')));
  for(const item of items){const card=n('article','', 'r1365-public-item');card.append(n('div',kindLabel(item.kind),'eyebrow'),n('h3',String(item.title||'').trim()),n('p',String(item.description||'').trim()));const meta=n('div','', 'r1332-offer-meta');if(item.promoCode)meta.append(n('span',t('Code: ')+item.promoCode));if(item.discountText)meta.append(n('span',item.discountText));if(item.startAt)meta.append(n('span',t('Starts ')+dateLabel(item.startAt)));if(item.endAt)meta.append(n('span',t(item.kind==='EVENT'?'Ends ':'Through ')+dateLabel(item.endAt)));if(item.eventLocation)meta.append(n('span',item.eventLocation));if(meta.childNodes.length)card.append(meta);const u=safe(item.actionUrl);if(u){const a=n('a',t(item.kind==='EVENT'?'Event details':'View details'),'button primary');a.href=u.href;a.rel='noopener noreferrer ugc';card.append(a)}const media=Array.isArray(item.media)?item.media:[];const images=media.filter(x=>String(x.mimeType||'').toLowerCase()==='image/webp'&&x.url);if(images.length){const gallery=n('div','', 'r1365-public-media');for(const image of images){const img=n('img');img.src=mediaUrl(image.url);img.alt=(item.title||t('Community Member promotion'))+' graphic';img.loading='lazy';img.decoding='async';gallery.append(img)}card.append(gallery)}const docs=media.filter(x=>String(x.mimeType||'').toLowerCase()==='application/pdf'&&x.url);for(const doc of docs){const a=n('a',t('View PDF document'),'button');a.href=mediaUrl(doc.url);a.rel='noopener noreferrer';a.target='_blank';card.append(a)}card.append(n('p',t('Provided by this Community Member. Franklin Navigator does not guarantee availability, terms or results.'),'fine-print'));section.append(card)}return insertSection(section)}
 async function legacy(){let out;try{const r=await fetch(API+'/api/member/public-profile?profileId='+encodeURIComponent(id),{credentials:'omit',cache:'no-store'});if(!r.ok)return;out=await r.json()}catch{return}if(out.activePaidMember!==true)return;const p=out.publication;if(!p||p.profileId!==id||p.provenance!=='MEMBER_SUBMITTED_REVIEWED')return;const f=p.fields||{},title=String(f.specialOfferTitle||'').trim(),details=String(f.specialOfferDetails||'').trim(),expires=String(f.specialOfferExpires||'').trim();if(!title||!details)return;if(expires&&/^\d{4}-\d{2}-\d{2}$/.test(expires)&&new Date(expires+'T23:59:59').getTime()<Date.now())return;const section=n('section','', 'hf35-member-module r1332-special-offer');section.id='member-offers-events';section.append(n('div',t('Community Member offer'),'eyebrow'),n('h2',t('Special offer for Franklin Navigator users')),n('h3',title),n('p',details));const meta=n('div','', 'r1332-offer-meta');if(String(f.specialOfferCode||'').trim())meta.append(n('span',t('Code: ')+String(f.specialOfferCode).trim()));if(expires)meta.append(n('span',t('Through ')+expires));if(meta.childNodes.length)section.append(meta);if(String(f.specialOfferTerms||'').trim())section.append(n('p',String(f.specialOfferTerms).trim(),'fine-print'));const u=safe(f.specialOfferUrl);if(u){const a=n('a',t('View offer'),'button primary');a.href=u.href;a.rel='noopener noreferrer ugc';section.append(a)}section.append(n('p',t('Offer provided by this Community Member. Franklin Navigator does not guarantee availability, terms or results.'),'fine-print'));insertSection(section)}
 let current=[];
 async function run(){let out;try{const r=await fetch(API+'/api/member/promotions/public?profileId='+encodeURIComponent(id),{credentials:'omit',cache:'no-store'});if(r.ok)out=await r.json()}catch{}current=out?.promotions||[];if(current.length&&renderCurrent(current))return;document.querySelector('#member-offers-events')?.remove();legacy()}
 const start=()=>{run();window.addEventListener('franklinlanguagechange',()=>{if(current.length)renderCurrent(current);else legacy()})};
 document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start,{once:true}):start();
})();
